#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>

// SHA-256 with AVX2: process 4 independent... no, single message is sequential.
// Instead, use AVX2 to speed up the message schedule and compression for a SINGLE block.
// This is complex. Let me instead just test raw AVX2 throughput for a simple operation to gauge.

int main(){
    size_t n = 20000*1024;
    unsigned char* data = malloc(n);
    for(size_t i=0;i<n;i++) data[i]=(unsigned char)i;
