    __m256i acc = _mm256_setzero_si256();
    clock_t t0=clock();
    for(int k=0;k<5;k++){
        acc = _mm256_setzero_si256();
        for(size_t i=0;i<n;i+=32){
            __m256i v = _mm256_loadu_si256((__m256i*)(data+i));
            acc = _mm256_xor_si256(acc, v);
        }
