    clock_t t1=clock();
    printf("AVX2 xor-sum: %.4f s (%.1f GB/s)\n", (double)(t1-t0)/CLOCKS_PER_SEC/5, n*5.0/((double)(t1-t0)/CLOCKS_PER_SEC)/1e9);
